def transform(grid):
    h, w = len(grid), len(grid[0])
    # The background is the most frequent color; replace enclosed background
    # regions (the interiors of outlined shapes) with 7.
    from collections import Counter, deque
    # The pattern fills the interiors of every rectangular outline. Fill any
    # enclosed cavity, regardless of the cavity's original color.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    outside = set()
    q = deque()
    for r in range(h):
        for c in (0, w - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    for c in range(w):
        for r in (0, h - 1):
            if grid[r][c] == bg and (r, c) not in outside:
                outside.add((r, c)); q.append((r, c))
    while q:
        r, c = q.popleft()
        for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    out = [row[:] for row in grid]
    # Also consider enclosed non-background cells (e.g. a differently colored
    # region nested within the background); preserve outline pixels.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r,c) not in outside:
                out[r][c] = 7
    return out

