def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Fill the interior of non-background rectangular outlines. Odd-area
    # cavities become 7; even-area cavities become 2.
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for color in set(v for row in grid for v in row):
        if color == background:
            continue
        for top in range(h):
            for left in range(w):
                if grid[top][left] != color:
                    continue
                for bottom in range(top + 2, h):
                    for right in range(left + 2, w):
                        if (grid[top][right] == color and grid[bottom][left] == color and grid[bottom][right] == color
                            and all(grid[top][c] == color and grid[bottom][c] == color for c in range(left, right + 1))
                            and all(grid[r][left] == color and grid[r][right] == color for r in range(top, bottom + 1))):
                            fill = 7 if ((bottom - top - 1) * (right - left - 1)) % 2 else 2
                            for r in range(top + 1, bottom):
                                for c in range(left + 1, right):
                                    out[r][c] = fill
    return out
